<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref} from 'vue';
import {ChevronDown,Plus,Clock3} from '@lucide/vue';
import {api,money} from '../types';
const props=defineProps<{conversationId:string;busy:boolean}>();
const emit=defineEmits<{changed:[];close:[]}>();
interface Schedule{transaction_name?:string;purpose?:string;generic?:boolean;id:string;recipient:string;recipient_name:string;recipient_detail:string;account_id:string;account_name:string;amount_yuan:string;amount_minor:number;execute_at:string;status:string;status_label:string;note:string;error?:string;execution_id?:string}
const expanded=ref(false),items=ref<Schedule[]>([]),error=ref(''),working=ref(false),editor=ref(false),recipient=ref(''),keyword=ref(''),amount=ref(''),execution=ref(''),note=ref(''),replaces=ref<Schedule|null>(null),candidates=ref<{id:string;name:string;detail:string}[]>([]),cancelling=ref('');
let timer:ReturnType<typeof setInterval>|undefined,polling=false;
function date(value:string){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
async function refresh(){if(polling)return;polling=true;try{items.value=(await api<{items:Schedule[]}>('/scheduled-transfers')).items;}catch(e){error.value=(e as Error).message;}finally{polling=false;}}
async function toggle(){expanded.value=!expanded.value;if(expanded.value)await refresh();}
function open(row?:Schedule){editor.value=true;error.value='';replaces.value=row||null;recipient.value=row?.recipient||'';keyword.value=row?.recipient_name||'';amount.value=row?.amount_yuan||'';note.value=row?.note||'';execution.value=row?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(row.execute_at)).replace(' ','T'):'';candidates.value=row?[{id:row.recipient,name:row.recipient_name,detail:row.recipient_detail}]:[];}
async function search(){if(!keyword.value.trim()||working.value)return;working.value=true;error.value='';try{candidates.value=(await api<{recipients:typeof candidates.value}>(`/scheduled-transfers/recipients?query=${encodeURIComponent(keyword.value.trim())}`)).recipients;recipient.value=candidates.value.length===1?candidates.value[0]!.id:'';if(!candidates.value.length)error.value='没有找到收款人或本人目标账户。';}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
async function create(){working.value=true;error.value='';try{const local=execution.value.length===16?execution.value+':00':execution.value;await api('/scheduled-transfers',{conversation_id:props.conversationId,recipient:recipient.value,amount_yuan:amount.value,execute_at:local+'+08:00',note:note.value,...(replaces.value?{replaces_id:replaces.value.id,account_id:replaces.value.account_id}:{})});editor.value=false;emit('changed');emit('close');}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
async function cancel(row:Schedule){working.value=true;error.value='';try{await api(`/scheduled-transfers/${encodeURIComponent(row.id)}/cancel`,{confirmation:'CANCEL'});cancelling.value='';await refresh();emit('changed');}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
onMounted(()=>{timer=setInterval(()=>{if(expanded.value&&!editor.value)void refresh();},2500);});
onBeforeUnmount(()=>clearInterval(timer));
</script>
<template>
<section class="panel-section schedule-section" aria-label="定时交易"><div class="section-heading"><h3><Clock3 :size="14"/>定时交易</h3><div class="schedule-actions"><button type="button" :disabled="busy||working" aria-label="新增定时转账" @click="open()"><Plus :size="13"/>新增</button><button type="button" :aria-label="expanded?'收起定时交易':'展开定时交易'" :aria-expanded="expanded" @click="toggle">{{expanded?'收起':'展开'}}<ChevronDown :size="14" :class="{rotate:expanded}"/></button></div></div>
  <div v-show="expanded"><p v-if="!items.length" class="schedule-note">暂无定时交易</p><article v-for="row in items" :key="row.id" class="schedule-row"><div><strong>{{row.account_name}} → {{row.transaction_name || row.recipient_name}}</strong><b>¥{{money(row.amount_minor)}}</b></div><p v-if="row.purpose">用途：{{row.purpose}}</p><div class="schedule-bottom"><time>{{date(row.execute_at)}}</time><button v-if="['scheduled','failed','needs_reauthorization'].includes(row.status)" type="button" :disabled="working" @click="cancel(row)">取消</button><span v-else>{{row.status_label}}</span></div></article><p v-if="error&&!editor" class="schedule-failed" role="alert">{{error}}</p></div>
  <div v-if="editor" class="investment-dialog-backdrop"><form class="investment-dialog" role="dialog" aria-modal="true" aria-label="定时交易授权" @submit.prevent="create"><h3>{{replaces?'修改并重新授权':'新增定时转账'}}</h3><p class="schedule-note">单次预约，最多提前365天。到点自动执行，无需再次输入密码；修改后需重新验证。</p><p v-if="replaces?.status==='scheduled'" class="schedule-failed">新授权完成前，原预约仍然有效。</p><label>收款人或本人目标账户<div class="schedule-search"><input aria-label="查找定时收款人" v-model="keyword" required maxlength="100" @input="recipient='';candidates=[]" placeholder="姓名、备注、银行卡尾号或账户名称"/><button type="button" :disabled="working||!keyword.trim()" @click="search">查找</button></div></label><label v-if="candidates.length">选择收款银行卡<select v-model="recipient" required aria-label="定时交易收款人"><option value="" disabled>请选择</option><option v-for="target in candidates" :key="target.id" :value="target.id">{{target.name}} · {{target.detail}}</option></select></label><label>金额（元）<input v-model="amount" required inputmode="decimal" pattern="(0|[1-9][0-9]{0,8})([.][0-9]{1,2})?" aria-label="定时交易金额"/></label><label>执行时间（北京时间）<input v-model="execution" type="datetime-local" required step="1" aria-label="定时交易执行时间"/></label><label>转账备注<input v-model="note" maxlength="120"/></label><p class="schedule-note">下一步核对授权卡，在验证窗口选择付款账户并输入支付密码；红色操作还需短信验证码。后台离线超过执行时间5分钟会停止，不自动补扣。</p><p v-if="error" class="schedule-failed" role="alert">{{error}}</p><div class="investment-buttons"><button type="button" :disabled="working" @click="editor=false">返回</button><button class="investment-primary" :disabled="busy||working||!recipient" type="submit">{{working?'正在核对…':'生成授权确认卡'}}</button></div></form></div>
</section>
</template>
<style scoped>
.section-heading h3{display:flex;align-items:center;gap:7px}.schedule-actions{display:flex;gap:12px}.schedule-actions button{display:flex;align-items:center;gap:4px;border:0;background:transparent;color:#819774;font:inherit;font-size:11px;cursor:pointer}.schedule-actions button:disabled{opacity:.45}.rotate{transform:rotate(180deg)}.schedule-note{font-size:11px;color:#8c9f7b;line-height:1.9}.schedule-row{padding:16px 0;border-top:1px solid #edf1e8}.schedule-row>div{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.schedule-row strong,.schedule-row b{font-weight:500}.schedule-row p{font-size:11px;line-height:1.8;color:#95a287;margin:7px 0;overflow-wrap:anywhere}.schedule-row span{font-size:10px;color:#6d8a59}.schedule-row small{font-size:9px;color:#a1ad96}.schedule-failed{color:#b17d60!important;font-size:11px;line-height:1.8}.schedule-bottom{margin-top:10px}.schedule-bottom time{font-size:11px;color:#95a287}.schedule-bottom button{border:0;background:transparent;color:#8d9f7e;font-size:11px;cursor:pointer}.schedule-controls{margin-top:10px;justify-content:flex-start!important;gap:12px!important}.schedule-controls button{border:0;background:transparent;color:#8d9f7e;font-size:10px;padding:0;cursor:pointer}.schedule-controls button:disabled{opacity:.4}.schedule-search{display:flex;gap:8px}.schedule-search input{min-width:0;flex:1}.schedule-search button{font:inherit;font-size:12px;background:#f1f5eb;border:1px solid #dce6d3;color:#6f895b;border-radius:8px;padding:6px 10px;cursor:pointer}
</style>
